func generateSearchParams(reqSearchParams map[string]interface{}) ([]*commonpb.KeyValuePair, error) {
    var searchParams []*commonpb.KeyValuePair
    var params interface{}
    if val, ok := reqSearchParams[Params]; ok { params = val }
    paramsMap := make(map[string]interface{})
    if params != nil { if paramsMap, ok = params.(map[string]interface{}); !ok { return nil, merr.WrapErrParameterInvalidMsg("searchParams.params must be a dict") } }
    ... 仅做 params 内同名键歧义检查 ...
    bs, _ := json.Marshal(paramsMap)
    searchParams = append(searchParams, &commonpb.KeyValuePair{Key: Params, Value: string(bs)})
键值原样 json.Marshal 透传——无已知键白名单、无值类型/域校验。'nprobes' 作为未知键随 JSON 下传，knowhere 侧忽略未识别键（IndexConfigGenerator 只在 interim 场景取 nprobe），故拼写错误静默降级到默认 nprobe。
